+                    KOKKOS_LAMBDA(size_t i, size_t j, size_t k) {
+                        if (i == 0 || j == 0 || i > size_t(nx) || j > size_t(ny))
+                            view(i, j, k) = Vector3D_t(0.);
+                    });
+            Kokkos::fence();
+        });
+    }
